  ('LBN-TAX-006', NULL, 'Stamp duty is one of Lebanon''s oldest taxes, applying to various documents and transactions. The law distinguishes between proportionate and fixed stamp duties.', 'en', 'Stamp Duty Law — Historical Context', 'Historical context and overview', 'Tax Law'),
  ('LBN-TAX-007', 'Law 296', 'Simplified foreign ownership rules and reduced registration fees to 5% for Lebanese and foreign investors', 'en', 'Real Estate Registration and Transfer Tax Law, Article Law 296', 'Foreign Ownership Rules', 'Tax Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LBN-TAX-007', 'Law 296', 'Faciliter l''investissement étranger et réduire les frais d''enregistrement', 'fr', 'Real Estate Registration and Transfer Tax Law, Article Law 296', 'Foreign Ownership Rules', 'Tax Law'),
